    "rpt.tab": "Parches", "rpt.unverified": "Original no comprobado", "rpt.verified": "Original comprobado",
    "rp.art": "Carátulas y marcos para cada consola con ROMs", "rp.body": "Cuerpo de RetroArch", "rp.button": "Llenar todo de una vez", "rp.cancel": "Cancelar", "rp.confirmTitle": "Llenar el pack de RetroArch", "rp.core": "Núcleo {name} ({sys}, {n} juegos)",
    "rp.creditBezel": "Marcos: hechos y compartidos por la comunidad de The Bezel Project. Gracias.", "rp.creditCover": "Carátulas: imágenes recogidas y compartidas por libretro-thumbnails. Gracias.",
    "rp.dirs": "Archivos que faltan en las carpetas info, assets y autoconfig", "rp.go": "Empezar a llenar", "rp.install": "Qué se instalará", "rp.lastFail": "El último llenado se detuvo: {err}",
    "rp.lastOk": "Último llenado: {i} instalados, {r} reemplazados, {k} archivos intactos, {b} carátulas, {z} marcos",
    "rp.lead": "Descarga el cuerpo de RetroArch, los núcleos de las consolas con ROMs y las carpetas info, assets y autoconfig del pack oficial de RetroArch, y luego trae carátulas y marcos. Los archivos que añadiste o cambiaste, retroarch.cfg y el sistema (BIOS) nunca se tocan.",
    "rp.notInBundle": "Los núcleos que el pack no tiene hay que añadirlos a mano: {names}", "rp.nothing": "No hay archivos que llenar. Solo se traerán carátulas y marcos.", "rp.size": "Tamaño de descarga: {size} (pack oficial de RetroArch {ver})",
    "rp.sizeCached": "El pack ya está descargado, así que no hay nada nuevo que traer.", "rp.started": "El llenado empezó. El progreso se ve en el menú de actividad.", "rp.state.current": "Ya es el mismo archivo", "rp.state.install": "Se instalará",
    "rp.state.modified": "Cambiado por ti, se queda como está", "rp.state.operator": "Archivo tuyo, se queda como está", "rp.state.replace": "Será reemplazado por la versión nueva", "rp.title": "Llenar RetroArch de una vez",
    "rk.approve": "Aprobar", "rk.approved": "Aprobado. El juego muestra este nombre ahora.", "rk.busy": "Leyendo hashes ahora.", "rk.by.crc32": "Hash de contenido (CRC-32)", "rk.by.sha1": "Hash de contenido (SHA-1)",
    "rk.by.sha256": "Hash de contenido (SHA-256)", "rk.by.title": "Título en inglés", "rk.colBy": "Emparejado por", "rk.colFile": "Archivo", "rk.colKo": "Título en coreano", "rk.colSystem": "Sistema",
    "rk.confirmedH": "Nombres confirmados por hash ({n})", "rk.guessH": "Sugerencias esperando aprobación ({n})",
    "rk.guessLead": "Estos nombres emparejaron solo con el título en inglés. Aprueba los correctos y rechaza los demás. Un nombre aprobado se guarda como nombre del juego y se muestra al momento. Una sugerencia rechazada no vuelve.",
    "rk.index": "Leer hashes de archivos nuevos",
    "rk.lead": "Los nombres coreanos de los juegos retro vienen del diccionario de un complemento de nombres, como OC Retro Database. Cuando el hash del contenido de una ROM coincide con el diccionario, el nombre se confirma y se muestra al momento. Cuando solo coincide el título en inglés, el nombre queda como sugerencia y solo se muestra tras aprobarlo aquí. Los archivos ROM solo se leen, nunca se cambian.", "rk.noSource": "No hay ningún complemento de nombres activo, así que no hay nombres coreanos que dar. Descarga y activa OC Retro Database en la pantalla de complementos.",
    "rk.more": "Mostrando los primeros {n}.", "rk.noConfirmed": "Aún no hay nombres confirmados por hash.", "rk.noGuess": "No hay sugerencias esperando.", "rk.reject": "Rechazar", "rk.rejected": "Rechazada. Esta sugerencia no volverá.",
    "rk.started": "Se empezó a leer hashes. Síguelo en el menú de actividad.", "rk.state": "Se leyeron los hashes de {read} de {files} archivos ROM. {skipped} archivos se saltaron.", "rk.tab": "Títulos coreanos",
    "dev.clientsLead": "Clientes descargados de la página web, listos para conectar. Cada uno lleva una clave de emparejamiento de su cuenta: dentro de 1 hora desde la descarga, hasta {n} consolas se aprueban para la cuenta la primera vez que la app arranca en ellas, y las demás se aprueban por QR. Una descarga nueva termina la clave anterior de la cuenta; las consolas ya conectadas se quedan. La clave en sí nunca se guarda en el servidor.",
    "f.type": "Tipo", "g.games": "Archivos", "g.homebrew": "Homebrew", "g.ops": "Operaciones", "g.overview": "Resumen", "g.people": "Cuentas", "g.retro": "Retro",
