    "t.restore": "Restaurer", "t.restoreSel": "Restaurer la sélection", "t.restored": "{n} éléments restaurés.", "t.restoredRenamed": "Restauré. Un fichier du même nom était déjà là, c'est donc maintenant {names}.",
