    "rpt.applied": "Gepatcht. Das Original ist separat gesichert.", "rpt.appliedUnverified": "Gepatcht. Ein IPS-Patch kann das Original nicht prüfen, darum wurde es als ungeprüft vermerkt.", "rpt.apply": "Patch hochladen", "rpt.applying": "Patcht {file}.",
    "rpt.askRestore": "{file} auf das Original von vor dem Patchen zurücksetzen? Jeder angewandte Patch geht dabei weg.", "rpt.colFile": "Datei", "rpt.colPatches": "Angewandte Patches", "rpt.colState": "Zustand", "rpt.colSystem": "System",
    "rpt.find": "Suchen", "rpt.foundH": "Gefundene Spiele",
    "rpt.lead": "Wendet eine koreanische Patchdatei (IPS, BPS, UPS, xdelta) auf eine Retro-ROM der Bibliothek an. Beim ersten Mal wird das Original in retro/.cookingfoil-originals gesichert, und das Ergebnis ersetzt die ROM unter demselben Dateinamen, sodass Cover und Rahmen bleiben. Eine Zip-ROM wird innen gepatcht und neu gepackt. BPS, UPS und xdelta lehnen ein Original ab, das nicht zum Patch passt, und lassen die Datei unangetastet. IPS kann das Original nicht prüfen, darum wird es als ungeprüft vermerkt. Original wiederherstellen setzt das gesicherte Original zurück.",
    "rpt.missing": "Von der Liste verschwunden", "rpt.no.arcade": "Arcade-Sets lassen sich nicht patchen", "rpt.no.multi-file": "Spiele aus mehreren Dateien lassen sich nicht patchen", "rpt.noFound": "Kein Spiel passt.", "rpt.noPatched": "Auf dem Server wurde noch kein Spiel gepatcht.",
    "rpt.original": "Original", "rpt.patched": "Koreanischer Patch", "rpt.patchedH": "Gepatchte Spiele", "rpt.restore": "Original wiederherstellen", "rpt.restored": "Original wiederhergestellt.", "rpt.search": "Spiel- oder Dateiname",
    "rpt.tab": "Patches", "rpt.unverified": "Original ungeprüft", "rpt.verified": "Original geprüft",
    "rp.art": "Cover und Rahmen für jede Konsole mit ROMs", "rp.body": "RetroArch-Rumpf", "rp.button": "Alles in einem Zug füllen", "rp.cancel": "Abbrechen", "rp.confirmTitle": "Das RetroArch-Pack füllen", "rp.core": "{name}-Kern ({sys}, {n} Spiele)",
    "rp.creditBezel": "Rahmen: gemacht und geteilt von der The-Bezel-Project-Community. Danke.", "rp.creditCover": "Cover: Bilder gesammelt und geteilt von libretro-thumbnails. Danke.",
    "rp.dirs": "Fehlende Dateien in den Ordnern info, assets und autoconfig", "rp.go": "Füllen starten", "rp.install": "Was installiert wird", "rp.lastFail": "Das letzte Füllen stoppte: {err}",
    "rp.lastOk": "Letztes Füllen: {i} installiert, {r} ersetzt, {k} Dateien unangetastet, {b} Cover, {z} Rahmen",
    "rp.lead": "Lädt den RetroArch-Rumpf, die Kerne der Konsolen mit ROMs und die Ordner info, assets und autoconfig aus dem offiziellen RetroArch-Paket herunter und holt danach Cover und Rahmen. Dateien, die du ergänzt oder geändert hast, retroarch.cfg und das System (BIOS) werden nie angerührt.",
    "rp.notInBundle": "Kerne, die das Paket nicht hat, musst du von Hand ergänzen: {names}", "rp.nothing": "Keine Dateien zu füllen. Es werden nur Cover und Rahmen geholt.", "rp.size": "Downloadgröße: {size} (offizielles RetroArch-Paket {ver})",
    "rp.sizeCached": "Das Paket ist schon geladen, es gibt nichts Neues zu holen.", "rp.started": "Das Füllen hat begonnen. Der Fortschritt steht im Aktivitätsmenü.", "rp.state.current": "Schon dieselbe Datei", "rp.state.install": "Wird installiert",
