    "lo.moved": "Перемещено файлов: {n}", "lo.newFolder": "Новая папка", "lo.noRecent": "Пока ничего не перемещалось.", "lo.notYet": "Ещё не проверено.", "lo.nothing": "Нечего перемещать",
